13803,-0.0030023726,0.02551519,0.016900644,-0.015657669,-0.029756583,-0.020663101,0.012654197,-0.00846426,-0.021103686,-0.025866352,0.022980953,-0.021149183,-0.021623218,0.0045517157,0.018288989,-0.0015464579,-0.046543635,-0.032654837,0.003531479,-0.02816676,0.002711669,-0.00808832,-0.011126331,-0.022775693,-0.03365713,-0.00878117,-0.034253366,0.01688602,-0.010719214,0.11492322,0.0404182,0.013246624,-0.016386177,0.0083497465,-0.01639505,0.019486642,-0.015988333,0.007648856,-0.03966209,0.040247865,0.020517873,0.019656839,0.00043053718,-0.008865931,-0.031695474,0.0010717267,-0.019373666,-0.023621377,0.0003004112,-0.019908575,0.014476985,-0.009970676,0.011924145,0.012460977,-0.011180171,-0.015160765,0.0022890219,-0.005747235,0.05431531,-0.05438374,-0.01144975,-0.031098299,0.041950125,0.007363412,-0.03082398]'::vector, now(), now());
