VALUES ('08f7a02e-2761-4299-9b24-a16bfd3e86d2', '00000000-0000-4000-8000-000000000400', 'The war had far-reaching political, economic, and social implications for both countries. In Somalia, it brought a massive influx of refugees from the north which, in turn, worsened the land and property rights of the local people. In Ethiopia, the victory encouraged Mengistu’s government to focus on fighting the northern opposition forces.', 'G10-History-STB-2023-web.pdf p.1', '2026.1', 'published', '[0.033763565,0.01546654,-0.010691786,-0.021230435,-0.0039004255,0.014456434,-0.021185359,0.027276186,0.008790292,-0.08268932,-0.004357951,-0.019043537,0.056110423,0.0037098525,-0.020727864,-0.023568172,0.03208344,-0.026467634,0.02107155,0.0020065608,0.01978232,0.019051362,0.025913686,0.013661195,0.0076505323,0.022728998,-0.040785503,-0.039213557,-0.012151658,0.20748572,-0.025573028,0.007576266,-0.01129247,0.016671436,0.0077489815,0.008230601,-0.026595008,0.0027137303,-0.0052541993,-0.007563067,-0.0007217787,-0.011250808,0.0076751327,0.051329564,0.037556596,0.022329047,0.0009813142,0.063400686,-0.030550215,0.015742537,0.007339667,-0.015281174,0.030689673,-0.08050777,0.020410491,0.04433928,0.02190287,0.0007112829,0.058063067,0.030377155,-0.018535743,-0.0018158715,-0.027088536,0.024270775,-0.013408426,-0.009009721,-0.001318601,-0.026461957,-0.013825692,0.019492539,-0.0043540434,-0.01574727,-0.028871985,-0.0056100297,-0.026189948,-0.004236475,-0.011353568,0.00063329755,0.031817183,0.020040363,-0.009507197,0.03508258,-0.047608126,0.03094008,0.023903962,0.003398406,0.02625004,-0.007535567,0.0076863673,0.015454167,0.020119734,0.04275451,-0.0050774426,-0.06599209,-0.0025546402,-0.019687466,-0.016304526,-0.045871846,-0.017522437,-0.0027448565,-0.032397874,0.038402557,0.027525706,-0.001440619,0.031015284,-0.00065156864,-0.008793126,0.039440263,0.058095764,0.010473264,-0.03835502,-0.3059148,-0.056977015,-0.047137894,-0.014889506,-0.05012138,0.01104181,0.0056286883,0.058292415,0.017524645,0.00